<?php

namespace App\Services\QrTypes;

use App\Models\QrCode;
use Illuminate\Http\Request;

class SocialHandler implements QrTypeHandler
{
    /**
     * Display a social media links page for the scanner.
     *
     * Expected content structure:
     * {
     *   "title": "Follow us",
     *   "description": "Find us on social media",
     *   "links": [
     *     { "platform": "facebook", "url": "https://..." },
     *     { "platform": "instagram", "url": "https://..." },
     *     ...
     *   ]
     * }
     */
    public function handle(QrCode $qrCode, Request $request): mixed
    {
        $title = $qrCode->content['title'] ?? $qrCode->title ?? 'Social Links';
        $description = $qrCode->content['description'] ?? '';
        $links = $qrCode->content['links'] ?? [];
        $theme = $qrCode->settings['theme'] ?? 'light';
        $layout = $qrCode->settings['layout'] ?? 'grid';

        $links = array_map(function ($link) {
            return [
                'platform' => $link['platform'] ?? '',
                'url' => $link['url'] ?? '#',
                'label' => $link['label'] ?? null,
                'icon' => $this->platformIcon($link['platform'] ?? ''),
            ];
        }, $links);

        return view('qr-types.social', [
            'qrCode' => $qrCode,
            'title' => $title,
            'description' => $description,
            'links' => $links,
            'theme' => $theme,
            'layout' => $layout,
        ]);
    }

